from pathlib import Path
import json, re

ROOT = Path('.')
P3 = ROOT/'works/tirumbippaar/transcription/parts/part-03-pdf-36-63.md'
P4 = ROOT/'works/tirumbippaar/transcription/parts/part-04-pdf-64-91.md'

def replace_required(text, old, new, label):
    if old not in text:
        raise SystemExit(f'Missing expected text for {label}: {old[:120]!r}')
    return text.replace(old, new, 1)

def replace_optional(text, old, new):
    if old in text:
        return text.replace(old, new, 1)
    return text

# ---------- part 03: PDF 54-63 ----------
t = P3.read_text(encoding='utf-8')
t = replace_required(t,
    '**Status:** `mixed` — PDF 36–53 / printed pp.28–45 are fidelity-verified; PDF 54–63 / printed pp.46–55 remain draft.',
    '**Status:** `verified` — PDF 36–63 / printed pp.28–55 have completed visual fidelity comparison against the rendered source scan.',
    'part03 status')
t = replace_required(t,
    'The rendered scan controls every reading. Source punctuation, English insertions, scene-marker irregularities and line order are preserved. PDF 36–53 have completed direct visual comparison. PDF 54–63 remain first-pass draft pending their own fidelity audit. PDF 61–63 were restored here after a pre-existing gap in the stored first-pass transcription was discovered during audit.',
    'The rendered scan controls every reading. Source punctuation, English insertions, scene-marker irregularities and line order are preserved. Every page in PDF 36–63 has completed direct visual comparison. PDF 61–63 remain documented as pages whose missing first-pass storage was discovered and repaired during the preceding audit activity; they have now also completed fidelity verification.',
    'part03 intro')
for p in range(54,64):
    printed=p-8
    t = replace_required(t, f'<!-- source: pdf={p} printed={printed} status=draft -->', f'<!-- source: pdf={p} printed={printed} status=verified -->', f'part03 anchor {p}')

